ls -la && python -c "
import torch
w = torch.load('weights.pt', map_location='cpu')
print(type(w))
if isinstance(w, dict):
    for k, v in w.items():
        if hasattr(v, 'shape'):
            print(k, tuple(v.shape), v.dtype)
        else:
            print(k, type(v), v)
"

python -c "
import torch
d = torch.load('dataset.pt', map_location='cpu')
print(type(d))
if isinstance(d, dict):
    for k, v in d.items():
        print(k, type(v), getattr(v,'shape',None), getattr(v,'dtype',None))
elif isinstance(d, (list,tuple)):
    print(len(d))
    for i,x in enumerate(d):
        print(i, type(x), getattr(x,'shape',None), getattr(x,'dtype',None))
"
